entries[67537] = { ["name"] = "Das Licht der Seelen", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Aktiviert das Licht der Seelen, was alle bösen Geister im Umkreis vernichtet. Für die Benutzung müsst Ihr Euch im Geisterreich befinden. (20 Sek. Abklingzeit)" }
entries[67538] = { ["name"] = "Rezept: Phiole der Sande", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Alchemie\n(525)\nBenutzen: Lehrt Euch die Herstellung der Phiole der Sande.\n\nPhiole der Sande\nReittier\nBenötigt Stufe 80\nBenötigt Erfahrenes Reiten\nBenutzen: Lehrt Euch, Euch in einen Drachen zu verwandeln, wodurch Ihr einen Verbündeten auf dem Rücken tragen könnt. Das ist ein Flugreittier.\nVerwandelt Euch in einen Sandsteindrachen, wodurch Ihr sehr schnell fliegen und einen Verbündeten auf dem Rücken tragen könnt. Das ist ein Flugreittier.\nVerkaufspreis:\nBenötigt Pyriumbeschichtete Kristallphiole , Sande der Zeit (8), Echtgold (12), Fläschchen der Winde (8), Fläschchen der Titanenstärke (8), Tiefsteinöl (8)" }
