entries[68820] = { ["name"] = "Stotterspritters Blaupausen", ["text"] = "Questgegenstand\n\"Die Blaupausen enthalten eine detaillierte Anleitung zum Bau der Silberblitz Â X-831.\"" }
entries[68823] = { ["name"] = "Gepanzerter Razzashiraptor", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 40\nBenötigt Geübtes Reiten\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren gepanzerten Razzashiraptor oder gibt ihn wieder frei." }
entries[68824] = { ["name"] = "Schneller zulianischer Panther", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 40\nBenötigt Geübtes Reiten\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen schnellen zulianischen Panther oder gibt ihn wieder frei." }
entries[68825] = { ["name"] = "Drachenfalke der Amani", ["text"] = "Einzigartig\nReittier\nBenötigt Stufe 60\nBenötigt Gekonntes Reiten\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren Drachenfalken der Amani oder gibt ihn wieder frei. Das ist ein Flugreittier." }
entries[68833] = { ["name"] = "Pantherjunges", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euer Pantherjunges beschwören oder wieder freigeben." }
entries[68837] = { ["name"] = "Dämonensaat", ["text"] = "Questgegenstand\n\"Leuchtet mit dämonischer Energie.\"" }
entries[68840] = { ["name"] = "Landros Lichling", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Landros Lichling beschwören oder wieder freigeben." }
entries[68841] = { ["name"] = "Nachtsäblerjunges", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euer Nachtsäblerjunges beschwören oder wieder freigeben." }
entries[68890] = { ["name"] = "Doppelpack Papierdrachen", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Lasst mit Eurem Waisenkind einen Papierdrachen steigen. (30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[68915] = { ["name"] = "Waagschalen des Lebens", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar: [Scales of Life] (1)\nSchmuck\n+575 Ausdauer\nBenötigt Stufe 85\nAnlegen: Speichert bis zu 17095 zusätzliche Gesundheit aus Zaubern, die Euch über Eure maximale Gesundheit hinaus heilen.\nBenutzen: Gibt sofort alle auf den Waagschalen des Lebens angesammelte Gesundheit als Selbstheilung frei. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[68925] = { ["name"] = "Wechselimpulsblitzkondensator", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Variable Pulse Lightning Capacitor] (1)\nSchmuck\n+406 Intelligenz\nBenötigt Stufe 85\nAnlegen: Ihr erhaltet eine elektrische Aufladung, wann immer Ihr einen kritischen Zaubertreffer erzielt, was eine Chance verleiht, einen Blitz abzufeuern, der pro gesammelter elektrischer Aufladung 985 to 1266 Schaden verursacht. Ihr könnt nicht mehr als 10 elektrische Aufladungen ansammeln und könnt nicht mehr als einmal alle 2,5 Sek. eine erhalten. (2.5s Abklingzeit)\nVerkaufspreis:" }
entries[68926] = { ["name"] = "Fänge des Schicksals", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Jaws of Defeat] (1)\nSchmuck\n+383 Intelligenz\nBenötigt Stufe 85\nBenutzen: Die nächsten 10 Zauber, die innerhalb der nächsten 20 Sek. gewirkt werden, reduzieren die Kosten Eurer Heilig- und Naturzauber um 110. Bis zu 10-mal stapelbar. (900ms Abklingzeit) (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[68927] = { ["name"] = "Der Hungerleider", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [The Hungerer] (1)\nSchmuck\n+383 Beweglichkeit\nBenötigt Stufe 85\nAnlegen: Eure Nahkampf- und Distanzangriffe haben eine Chance, Eure Tempowertung 15 Sek. lang um 1532 zu erhöhen. (1Min. Abklingzeit)\nVerkaufspreis:" }
entries[68937] = { ["name"] = "Düsterhammers Stiefel", ["text"] = "Questgegenstand\nEinzigartig\n\"Diese Stiefel haben schon bessere Tage gesehen.\"" }
entries[68955] = { ["name"] = "Totem von Tortolla", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Umhüllt Euch 10 Sek. lang mit einem undurchdringlichen Panzer. (20 Sek. Abklingzeit)" }
entries[68972] = { ["name"] = "Apparat von Khaz'goroth", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar: [Apparatus of Khaz'goroth] (1)\nSchmuck\n+383 Stärke\nBenötigt Stufe 85\nAnlegen: Eure kritischen Nahkampftreffer gewähren Euch Titanische Kraft, mit der Ihr diesen Apparat betreiben könnt. Die Titanische Kraft ist bis zu 5-mal stapelbar und hält 30 Sek. lang an.\nBenutzen: Zehrt sämtliche titanische Kraft auf, um Eure kritische Trefferwertung, Tempowertung oder Meisterschaftswertung pro angesammelter Titanischer Kraft um 508 zu erhöhen. Hält 15 Sek. lang an. Der Apparat wird immer die höchste dieser drei Wertungen auswählen. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[68981] = { ["name"] = "Spinnenseidenspindel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Spidersilk Spindle] (1)\nSchmuck\nErhöht Eure Meisterschaftswertung um + 383.\nBenötigt Stufe 85\nAnlegen: Nahkampfangriffe, die Eure Gesundheit unter 35% fallen lassen, verleihen Euch einen Schutzschild, der 30 Sek. lang 17095 Schaden absorbiert. Kann nicht öfter als ein Mal pro Minute auftreten. (1Min. Abklingzeit)\nVerkaufspreis:" }
entries[68982] = { ["name"] = "Nekromantischer Fokus", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Necromantic Focus] (1)\nSchmuck\n+383 Intelligenz\nBenötigt Stufe 85\nAnlegen: Jedes Mal, wenn Ihr regelmäßigen Zauberschaden verursacht, gewinnt Ihr 10 Sek. lang 39 Meisterschaftswertung. Bis zu 10-mal stapelbar.\nVerkaufspreis:" }
