entries[69224] = { ["name"] = "Schwelendes Ei von Millagazor", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 70\nBenötigt Gekonntes Reiten\nBenutzen: Lehrt Euch, wie Ihr einen Reinblut-Feuerfalken beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren Reinblut-Feuerfalken oder gibt ihn wieder frei. Das ist ein Flugreittier." }
entries[69225] = { ["name"] = "Fangzahn des Wolfs", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Kanalisiert den Geist des Wolfsahnen und ruft Lylagar aus seinem Versteck. (15 Sek. Abklingzeit)" }
entries[69226] = { ["name"] = "Grüner Feuerfalke", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 70\nBenötigt Gekonntes Reiten\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren grünen Feuerfalken oder gibt ihn wieder frei. Das ist ein Flugreittier." }
entries[69227] = { ["name"] = "Katzengold", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Rechtsklicken, um ein Katzengoldvorkommen zu platzieren.\n\nSpieler können das Vorkommen benutzen, um vorübergehend Gierige Kobolde als Haustiere zu beschwören. (30 Min Abklingzeit)" }
entries[69228] = { ["name"] = "Wilder Raptor", ["text"] = "Einzigartig\nReittier\nBenötigt Stufe 20\nBenötigt Unerfahrener Reiter\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren wilden Raptor oder gibt ihn wieder frei." }
entries[69230] = { ["name"] = "Verderbtes Ei von Millagazor", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 70\nBenötigt Gekonntes Reiten\nBenutzen: Lehrt Euch, wie Ihr einen verderbten Feuerfalken beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren verderbten Feuerfalken oder gibt ihn wieder frei. Das ist ein Flugreittier." }
entries[69231] = { ["name"] = "Doppelpack Papierdrachen", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Lasst mit Eurem Waisenkind einen Papierdrachen steigen. (30 Sek. Abklingzeit)\nVerkaufspreis:" }
