entries[69645] = { ["name"] = "Stab des Wächters", ["text"] = "Questgegenstand\n\"Ein großer Ast, einfach entzweigt und als Stab verwendet.\"" }
entries[69646] = { ["name"] = "Zweig von Nordrassil", ["text"] = "Questgegenstand\n\"Entrissen von Nordrassil und gebadet in den Flammen der Feuerlande, bebt dieser Stab mit den vereinten Mächten.\"" }
entries[69647] = { ["name"] = "Mysteriöses Schmuckstück der Gurubashi", ["text"] = "Questgegenstand\nEinzigartig\n\"Ihr spürt, dass diesem Gegenstand etwas Jenseitiges anhaftet.\"" }
entries[69648] = { ["name"] = "Beinchen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick Beinchen beschwören oder wieder freigeben." }
entries[69649] = { ["name"] = "Unverdächtiger Smaragd", ["text"] = "Questgegenstand\nEinzigartig\n\"Scheint... magisch.\"" }
entries[69650] = { ["name"] = "Totem von Tortolla", ["text"] = "Questgegenstand\nEinzigartig\n\"Wird sich später sicherlich als praktisch erweisen...\"" }
entries[69675] = { ["name"] = "Getrocknete Eichel", ["text"] = "Questgegenstand\n\"Ein kleines, getrocknetes Samenkorn.\"" }
entries[69677] = { ["name"] = "Sulfurgetränkte Bandagen", ["text"] = "Questgegenstand\n\"Sie sind groß und stinken.\"" }
entries[69678] = { ["name"] = "Flammenumwundenes Herz", ["text"] = "Questgegenstand\n\"Ein zischendes Stück Stein, das aus der Brust eines Elitekämpfers von Ragnaros gerissen wurde.\"" }
entries[69679] = { ["name"] = "Flammenschürerschuppe", ["text"] = "Questgegenstand\n\"Seid vorsichtig... sie sind ziemlich scharfkantig.\"" }
entries[69691] = { ["name"] = "Medaillon des Staffelführers", ["text"] = "Questgegenstand\nEinzigartig\n\"Weist Euch als Anführer einer druidischen Kampfgruppe in Sethrias Nest aus.\"" }
entries[69722] = { ["name"] = "Glutharz", ["text"] = "Questgegenstand\n\"Die geschmolzene Substanz fühlt sich heiß an.\"" }
entries[69723] = { ["name"] = "Herz eines Lavawurms", ["text"] = "Questgegenstand\n\"Feuer fließt durch seine Adern.\"" }
entries[69724] = { ["name"] = "Tempelratte", ["text"] = "Zul'Gurub\nHerbeigezauberter Gegenstand\nEinzigartig\nBenutzen: Werft diesen leckeren Bissen in die Nähe eines Panthers aus Hohepriesterin Kilnaras Rudel, um ihn in einen Blutrausch zu versetzen." }
entries[69725] = { ["name"] = "Magmolie", ["text"] = "Questgegenstand\n\"Diese glimmende Blüte könnte alles, was sie berührt, in Flammen aufgehen lassen.\"" }
entries[69747] = { ["name"] = "Kampfbär der Amani", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 85\nBenötigt Geübtes Reiten\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren Kampfbären der Amani oder gibt ihn wieder frei." }
entries[69748] = { ["name"] = "Zerlumpter Beutel aus Hexerstoff", ["text"] = "Wird beim Aufheben gebunden\n24 Platz Behälter\n\"Hergestellt aus Stofffetzen aus den Tiefen von Zul'Aman.\"\nVerkaufspreis:" }
entries[69749] = { ["name"] = "Stickrankensamen", ["text"] = "Questgegenstand\n\"Die Samen pulsieren mit einem seltsamen Leuchten, bereit, in der richtigen Umgebung zu bersten.\"" }
entries[69750] = { ["name"] = "Sporenspray", ["text"] = "Questgegenstand\n\"Sprüht die Gegend um Euch mit einem feinen Nebel ein und deckt alle Sporen auf, die der Feuerpeitscher zurückgelassen hat.\"" }
